// Whole-width paths keep tab and folder rules connected.
(()=>{const tabs=[...document.querySelectorAll('.folder-tab')];
const frame=document.createElementNS('http://www.w3.org/2000/svg','svg'),edge=document.createElementNS('http://www.w3.org/2000/svg','path');frame.id='folder-outline';frame.setAttribute('aria-hidden','true');frame.append(edge);document.body.append(frame);
function draw(){const w=document.documentElement.clientWidth,h=innerHeight;frame.setAttribute('viewBox',`0 0 ${w} ${h}`);edge.setAttribute('d',`M ${w-3} 74 V ${h-15} Q ${w-3} ${h-3} ${w-15} ${h-3} H 14 Q 2 ${h-3} 2 ${h-15} V 64`);for(const tab of tabs){const svg=tab.querySelector('svg'),selected=tab.classList.contains('selected'),x=tab.offsetLeft,b=64,t=8,r=tab.offsetWidth;const d=(x===0?`M 2 ${b}`:`M 0 ${b} H ${x+2}`)+` C ${x+9} ${b} ${x+12} ${t} ${x+27} ${t} H ${x+r-32} C ${x+r-15} ${t} ${x+r-13} ${b} ${x+r} ${b} H ${w-14} Q ${w-3} ${b} ${w-3} ${b+10}`;svg.style.width=w+'px';svg.setAttribute('viewBox',`0 0 ${w} 76`);svg.querySelector('.tab-edge').setAttribute('d',d);svg.querySelector('.tab-fill').setAttribute('d',d+` V 76 H 2 Z`);}}
new MutationObserver(draw).observe(document.querySelector('.folder-tabs'),{subtree:true,attributes:true,attributeFilter:['class']});addEventListener('resize',draw);draw();})();
